class Solution {
public:
    vector<int> colorTheArray(int n, vector<vector<int>>& queries) {
        vector<int> col(n, 0), ans;
        int c = 0;
        for (auto& q : queries) {
            int i = q[0], x = q[1];
            if (col[i] != 0) {
                if (i > 0 && col[i-1] == col[i]) c--;
                if (i < n - 1 && col[i+1] == col[i]) c--;
            }
            col[i] = x;
            if (i > 0 && col[i-1] == x) c++;
            if (i < n - 1 && col[i+1] == x) c++;
            ans.push_back(c);
        }
        return ans;
    }
};

