class Solution {
    public int[] colorTheArray(int n, int[][] queries) {
        int[] col = new int[n];
        int c = 0;
        int[] ans = new int[queries.length];
        for (int k = 0; k < queries.length; k++) {
            int i = queries[k][0], x = queries[k][1];
            if (col[i] != 0) {
                if (i > 0 && col[i-1] == col[i]) c--;
                if (i < n - 1 && col[i+1] == col[i]) c--;
            }
            col[i] = x;
            if (i > 0 && col[i-1] == x) c++;
            if (i < n - 1 && col[i+1] == x) c++;
            ans[k] = c;
        }
        return ans;
    }
}

