var colorTheArray = function(n, queries) {
    const col = new Array(n).fill(0);
    let c = 0;
    const ans = [];
    for (const [i, x] of queries) {
        if (col[i] !== 0) {
            if (i > 0 && col[i-1] === col[i]) c--;
            if (i < n - 1 && col[i+1] === col[i]) c--;
        }
        col[i] = x;
        if (i > 0 && col[i-1] === x) c++;
        if (i < n - 1 && col[i+1] === x) c++;
        ans.push(c);
    }
    return ans;
};
